import json,re
def strict(s, clip=300):
    if len(s)>clip: s=s[-clip:]
    sols=re.findall(r'#### (\-?[0-9\.\,]+)', s)
    if not sols: return None
    return sols[-1].replace(',','').replace('\$','').replace('\$','')
for fn in ['results/run100/val_generations/0.jsonl','results/run100/val_generations/50.jsonl','results/run100/val_generations/100.jsonl']:
    rows=[json.loads(l) for l in open(fn) if l.strip()]
    mism=[]; agree=0; n=len(rows)
    fmt=sum(1 for r in rows if '####' in r['output'])
    corr=sum(1 for r in rows if r['score']>0)
    for r in rows:
        pred=strict(r['output'])
        mine = 1.0 if (pred is not None and pred==str(r['gts'])) else 0.0
        if abs(mine-r['score'])>1e-9: mism.append((r['input'][-60:],r['output'][-120:],pred,r['gts'],r['score']))
        else: agree+=1
    print(fn,'n=',n,'agree=',agree,'mismatch=',len(mism),'has####=',fmt,'scored>0=',corr)
    for m in mism[:3]: print('   ',m)
"

