import json, pandas as pd, re
inst='Let\'s think step by step and output the final answer after \"####\".'
tr=pd.read_parquet('data/raw/gsm8k/main/train-00000-of-00001.parquet')
te=pd.read_parquet('data/raw/gsm8k/main/test-00000-of-00001.parquet')
def gold(ans):
    m=re.search(r'#### (\-?[0-9\.\,]+)',ans); return m.group(1).replace(',','')
trmap={q:gold(a) for q,a in zip(tr.question,tr.answer)}
temap={q:gold(a) for q,a in zip(te.question,te.answer)}
def q_from_input(inp):
    # strip chat template: take text between 'user' and 'assistant'
    m=re.search(r'user\n(.*?)\nassistant', inp, re.S)
    return m.group(1)
for fn in ['val_generations/0.jsonl','rollouts/100.jsonl','rollouts/50.jsonl','rollouts/1.jsonl']:
    rows=[json.loads(l) for l in open('results/run100/'+fn) if l.strip()]
    intrain=intest=neither=0; gtmatch=0
    for r in rows:
        q=q_from_input(r['input'])
        q=q[:-(len(inst)+1)] if q.endswith(' '+inst) else q
        if q in temap:
            intest+=1; gtmatch+= (temap[q]==str(r['gts']))
        elif q in trmap:
            intrain+=1; gtmatch+= (trmap[q]==str(r['gts']))
        else: neither+=1
    print(fn,'rows',len(rows),'| from TEST:',intest,'from TRAIN:',intrain,'neither:',neither,'| gt match:',gtmatch)
"

