    for k in path.split('/'): d=d[k]
    return d
series={}
for r in rows:
    step=r['step'] if 'step' in r else r['data'].get('training/global_step')
    series.setdefault('step',[]).append(step)
    for k in ['actor/entropy','response_length/clip_ratio','response_length/mean','response_length/max',
              'actor/kl_loss','actor/pg_clipfrac','actor/pg_clipfrac_lower','actor/grad_norm','actor/loss','actor/pg_loss',
