              'rollout_corr/rollout_log_ppl','rollout_corr/kl','rollout_corr/chi2_token','rollout_corr/ppl_ratio',
              'training/rollout_actor_probs_pearson_corr','training/rollout_probs_diff_mean',
              'response/aborted_ratio','actor/ppo_kl','prompt_length/clip_ratio',
              'val-core/openai/gsm8k/acc/mean@1','val-aux/openai/gsm8k/reward/mean@1',
              'actor/lr','perf/time_per_step','response_length_non_aborted/clip_ratio']:
        try: series.setdefault(k,[]).append((step,get(r['data'],k)))
        except Exception: series.setdefault(k,[]).append((step,None))

for k in ['val-core/openai/gsm8k/acc/mean@1']:
    print(k, [f"{s}:{v:.4f}" for s,v in series[k] if v is not None])
for k in ['actor/entropy','response_length/clip_ratio','response_length_non_aborted/clip_ratio','response_length/mean']:
    vs=[(s,v) for s,v in series[k] if v is not None]
